clc; clearvars;
%%
dz = 3.75;

sg = load('sg_filters.mat');
sg_diff = sg.sg_diff;

N = 1:length(sg_diff)';
M = (N*2)+1;

fc = resolution_FC(sg_diff,dz);
ir = resolution_IR(sg_diff,dz);
%%
figure; %[output:64981488]
plot(fc,M,'DisplayName','FC') %[output:64981488]
hold on %[output:64981488]
plot(ir,M,'DisplayName','IR') %[output:64981488]
hold off %[output:64981488]
ylabel('Filter Width') %[output:64981488]
xlabel('Resolution (m)') %[output:64981488]
grid on %[output:64981488]
legend %[output:64981488]

